INSERT INTO `affiliate_videos` VALUES (1,22,29,'Review MacBook Air M4 sau 7 ngày sử dụng – Có đáng mua?','Sau 7 ngày trải nghiệm MacBook Air M4, mình đánh giá đây là chiếc laptop rất phù hợp cho sinh viên, dân văn phòng và người làm sáng tạo nội dung. Hiệu năng mượt, pin lâu và thiết kế đẹp. Nếu đang tìm một chiếc laptop để học tập hoặc làm việc lâu dài thì đây là lựa chọn rất đáng cân nhắc.',NULL,'https://www.youtube.com/watch?v=iIe99_4xGIM','affiliate-videos/thumbnails/aSnqCM2ziyhayyvK2ix2M4dF8mVYV5FlBSwAJqnw.jpg','approved',0,44,3,NULL,'2026-07-13 08:33:05','2026-07-13 07:42:39','2026-08-10 13:46:59'),(2,22,NULL,'ASUS TUF Gaming A16 – Laptop gaming đáng mua trong tầm giá?','ASUS TUF Gaming A16 sở hữu hiệu năng mạnh mẽ với thiết kế bền bỉ, màn hình 144Hz mượt mà và khả năng chiến tốt nhiều tựa game phổ biến. Đây là lựa chọn phù hợp cho cả game thủ lẫn người làm đồ họa.',NULL,'https://www.youtube.com/watch?v=KrDydDVq9oQ','affiliate-videos/thumbnails/rJCnCle4xONpgwOLZWCXfKxntSmMHk2T0TiPzuLz.jpg','approved',1,89,4,NULL,'2026-07-13 08:24:22','2026-07-13 08:23:51','2026-08-11 05:10:30'),(3,22,NULL,'Dell XPS 13 - Chiếc laptop văn phòng cao cấp có thực sự đáng mua?','Dell XPS 13 là mẫu ultrabook cao cấp với thiết kế sang trọng, màn hình sắc nét và hiệu năng ổn định. Nếu bạn đang tìm một chiếc laptop phục vụ học tập, làm việc hay lập trình thì đây là lựa chọn rất đáng cân nhắc.',NULL,'https://www.youtube.com/watch?v=jGATmmW1VOM','affiliate-videos/thumbnails/Ej9IGOhSIGDoLfn2ZTGlD75hXLgiVG2iP5AvDHey.jpg','approved',1,81,5,NULL,'2026-07-13 08:36:18','2026-07-13 08:35:55','2026-08-11 11:38:15'),(4,22,NULL,'Top 3 Laptop đáng mua cho sinh viên Công nghệ thông tin năm 2026','Chọn laptop phù hợp sẽ giúp bạn học tập và làm việc hiệu quả hơn. Dưới đây là 3 mẫu laptop nổi bật dành cho sinh viên CNTT với mức giá và hiệu năng phù hợp.',NULL,'https://www.youtube.com/watch?v=RE7zh5eKAmk','affiliate-videos/thumbnails/GxC7Pkk7sf78BgKT697BzvBRikq6Px2S7NzswiGs.png','approved',1,36,2,NULL,'2026-07-13 08:39:15','2026-07-13 08:38:43','2026-08-11 11:37:29');
