INSERT INTO `combos` VALUES (1,'Combo Bàn phím Logitech G Pro X TKL Light Speed + Chuột Gaming Logitech G102 LightSync Gen 2','uploads/sanpham/860d02bf1cc1683fbde3d3b1193b6080.png','Combo gồm bàn phím Logitech G Pro X TKL Lightspeed và chuột Logitech G102 Lightsync Gen 2, mang đến trải nghiệm gaming mượt mà với thiết kế hiện đại, độ chính xác cao và hệ thống đèn RGB nổi bật. Phù hợp cho game thủ, học tập và làm việc hằng ngày.',2457000.00,1,'2026-05-27 14:27:40','2026-05-27 14:40:37');
