-- Table structure for table `dathang_chitiet`
--

DROP TABLE IF EXISTS `dathang_chitiet`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `dathang_chitiet` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `id_dathang` bigint(20) unsigned NOT NULL,
  `id_bienthe` bigint(20) unsigned NOT NULL,
  `soluong` int(11) NOT NULL,
  `gia` decimal(12,2) NOT NULL,
  `id_combo` bigint(20) unsigned DEFAULT NULL,
  `id_nhom_combo` varchar(255) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `hoantien` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `dathang_chitiet_id_dathang_foreign` (`id_dathang`),
  KEY `dathang_chitiet_id_bienthe_foreign` (`id_bienthe`),
  KEY `dathang_chitiet_id_combo_foreign` (`id_combo`),
  CONSTRAINT `dathang_chitiet_id_bienthe_foreign` FOREIGN KEY (`id_bienthe`) REFERENCES `bienthe` (`id_bienthe`),
  CONSTRAINT `dathang_chitiet_id_combo_foreign` FOREIGN KEY (`id_combo`) REFERENCES `combos` (`id_combo`) ON DELETE SET NULL,
  CONSTRAINT `dathang_chitiet_id_dathang_foreign` FOREIGN KEY (`id_dathang`) REFERENCES `dathang` (`id_dathang`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=368 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

