  CONSTRAINT `giohang_id_combo_foreign` FOREIGN KEY (`id_combo`) REFERENCES `combos` (`id_combo`) ON DELETE SET NULL,
  CONSTRAINT `giohang_user_id_foreign` FOREIGN KEY (`id_khachhang`) REFERENCES `khachhang` (`id`) ON DELETE CASCADE
