DROP TABLE IF EXISTS `khachhang`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `khachhang` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `ten` varchar(255) NOT NULL,
  `email` varchar(255) NOT NULL,
  `anhdaidien` text DEFAULT NULL,
  `face_descriptor` longtext DEFAULT NULL,
  `face_registered` tinyint(1) NOT NULL DEFAULT 0,
  `sodienthoai` varchar(255) DEFAULT NULL,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `matkhau` varchar(255) NOT NULL,
  `vaitro` varchar(50) NOT NULL DEFAULT 'user',
  `id_facebook` varchar(255) DEFAULT NULL,
  `id_google` varchar(255) DEFAULT NULL,
  `two_factor_secret` text DEFAULT NULL,
  `two_factor_recovery_codes` text DEFAULT NULL,
  `two_factor_confirmed_at` timestamp NULL DEFAULT NULL,
  `remember_token` varchar(100) DEFAULT NULL,
  `api_token` varchar(64) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `ngaysinh` date DEFAULT NULL,
  `gioitinh` varchar(10) DEFAULT NULL,
  `trangthai` enum('active','locked') NOT NULL DEFAULT 'active',
  `xu` int(11) NOT NULL DEFAULT 0,
  `otp_khoiphuc` varchar(10) DEFAULT NULL,
  `otp_khoiphuc_hethan_luc` timestamp NULL DEFAULT NULL,
  `hoat_dong_cuoi_luc` timestamp NULL DEFAULT NULL,
  `luot_quay` int(10) unsigned NOT NULL DEFAULT 3,
  PRIMARY KEY (`id`),
  UNIQUE KEY `users_email_unique` (`email`),
  UNIQUE KEY `users_api_token_unique` (`api_token`),
  KEY `khachhang_id_google_index` (`id_google`)
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
